"""Claude Code target: the managed CLAUDE.md block and everything under .claude/."""

import json
from collections.abc import Iterable, Iterator
from types import MappingProxyType

from oees_agents.content import Content, Document, Skill
from oees_agents.context import context_block
from oees_agents.manifest import Manifest
from oees_agents.output import ManagedBlock, Output
from oees_agents.profiles import KIT_TOOLCHAINS, SUBAGENT_ONLY_SKILLS, Toolchain

ROOT = ".claude"
RULES_HEADER = (
    "## Shared engineering rules\n"
    "Generated by oees-agents from `.oees-agents.toml`. Edit the manifest and run "
    "`oees-agents update`; keep project instructions outside this block."
)

BASE_ALLOW = tuple(
    f"Bash({command}*)"
    for command in (
        "git status",
        "git diff",
        "git log",
        "git show",
        "git branch",
        "git add",
        "git commit",
        "git stash",
        "git rebase",
        "git fetch",
        "ls",
        "find",
        "grep",
        "cat",
        "head",
        "tail",
        "wc",
        "mkdir",
        "mv",
        "cp",
        "touch",
    )
)
TOOLCHAIN_ALLOW: dict[Toolchain, tuple[str, ...]] = {
    "python": (
        "Bash(uv*)",
        "Bash(pytest*)",
        "Bash(ruff*)",
        "Bash(mypy*)",
        "Bash(python -m pytest*)",
    ),
    "typescript": (
        "Bash(npm run lint*)",
        "Bash(npm run test*)",
        "Bash(npm run build*)",
        "Bash(npm run typecheck*)",
        "Bash(npm test*)",
        "Bash(tsc*)",
        "Bash(eslint*)",
        "Bash(npx tsc*)",
    ),
}
DENY = (
    "Bash(git push*)",
    "Bash(git push --force*)",
    "Bash(git reset --hard*)",
    "Bash(git rebase -i*)",
    "Bash(git rebase --interactive*)",
    "Bash(git filter-branch*)",
)


def render(manifest: Manifest, content: Content) -> Output:
    rules = [*content.conduct.values(), *(content.defaults[name] for name in manifest.defaults)]
    files = {
        **_documents("rules", rules),
        **_skill_files(_skills(manifest, content)),
        **_documents("agents", _subagents(manifest, content)),
        **_documents("loops", (content.loops[name] for name in manifest.extras.loops)),
        f"{ROOT}/settings.json": _settings(manifest),
    }
    if manifest.extras.commands:
        files.update(_documents("commands", content.commands.values()))
    block = ManagedBlock(body=_claude_md(manifest, content, rules), placement="top")
    return Output(
        files=MappingProxyType(dict(sorted(files.items()))),
        blocks=MappingProxyType({f"{ROOT}/CLAUDE.md": block}),
    )


def _claude_md(manifest: Manifest, content: Content, rules: list[Document]) -> str:
    imports = "\n".join(f"@rules/{rule.name}.md" for rule in rules)
    section = f"{RULES_HEADER}\n\n{imports}\n"
    context = context_block(manifest, content)
    return section if context is None else f"{context}\n{section}"


def _documents(directory: str, documents: Iterable[Document]) -> dict[str, bytes]:
    return {f"{ROOT}/{directory}/{document.name}.md": document.raw for document in documents}


def _skills(manifest: Manifest, content: Content) -> Iterator[Skill]:
    with_subagents = manifest.extras.subagents != "none"
    for skill in content.skills.values():
        if with_subagents or skill.name not in SUBAGENT_ONLY_SKILLS:
            yield skill
    for name in manifest.kits:
        yield content.kits[name]


def _skill_files(skills: Iterable[Skill]) -> dict[str, bytes]:
    return {
        f"{ROOT}/skills/{skill.name}/{relative}": data
        for skill in skills
        for relative, data in skill.files.items()
    }


def _subagents(manifest: Manifest, content: Content) -> Iterator[Document]:
    tiers = {"none": (), "core": ("core",), "extended": ("core", "extended")}
    for tier in tiers[manifest.extras.subagents]:
        yield from content.subagents[tier].values()


def _settings(manifest: Manifest) -> bytes:
    allow = list(BASE_ALLOW)
    if manifest.project is not None:
        checks = (manifest.project.check, manifest.project.check_fast)
        allow += [f"Bash({check.strip()}*)" for check in checks if check.strip()]
    toolchains = (chain for kit in manifest.kits for chain in KIT_TOOLCHAINS.get(kit, ()))
    for toolchain in dict.fromkeys(toolchains):
        allow += TOOLCHAIN_ALLOW[toolchain]
    data = {"permissions": {"allow": list(dict.fromkeys(allow)), "deny": list(DENY)}}
    return (json.dumps(data, indent=2) + "\n").encode()
